import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from '@/lib/utils'
import { Slot } from "radix-ui"

/*
 * GENERATED BY `shadcn add badge`, WITH THE VARIANT SET REPLACED.
 *
 * Upstream's base keeps its shape; four values in it are this project's,
 * and each is a token the stylesheet had hand-written:
 *
 *   px-2    -> px-2.25            9px, which `_decisions.md` settles as a
 *                                 fractional step rather than a new token
 *   text-xs -> text-sm            `01-tokens` redefined the scale: `--text-xs`
 *                                 is 11px here, and the pill has always been 12
 *   border-transparent
 *           -> border-border-strong  the pill IS its outline
 *   (none)  -> text-secondary-text   the base colour every variant overrides
 *
 * THE VARIANTS ARE KEYED ON THE DOMAIN UNIONS, not on shadcn's
 * default/secondary/destructive. `<Badge variant={op.status}>` is then a
 * COMPILE ERROR the day the server adds a fifth status -- which is the bug
 * this unit leads with, because today it renders an outlined pill with
 * nothing inside it, and an empty pill is colour alone.
 */
const badgeVariants = cva(
  "inline-flex w-fit shrink-0 items-center justify-center gap-1 overflow-hidden rounded-full border border-border-strong px-2.25 py-0.5 text-sm font-medium whitespace-nowrap text-secondary-text transition-[color,box-shadow] focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&>svg]:pointer-events-none [&>svg]:size-3",
  {
    variants: {
      /*
       * Three of these are deliberately EMPTY, and they are written out
       * rather than omitted so the next reader sees a decision instead of a
       * gap. `closed` and `position` are the ordinary cases and the ordinary
       * case should spend no colour; neither had a selector in `styles.css`
       * either, and no grep could have told you whether that was on purpose.
       */
      variant: {
        // OperationStatus
        open: "border-series-lp text-series-lp",
        closed: "",
        incomplete: "border-dashed text-muted-text",
        "set-aside": "border-dashed text-muted-text",

        // Episode kind
        position: "",
        unpredicted: "border-dashed text-muted-text",

        // Verdict -- each mistake is its own WORD before it is a colour, which
        // is why `too-narrow` and `too-wide` are not one `bad`: they are
        // opposite failures with opposite fixes.
        "too-narrow": "border-bad text-bad",
        "too-wide": "border-series-hodl text-series-hodl",
        "well-sized": "border-good text-good",
      },
    },
    defaultVariants: {
      variant: "closed",
    },
  }
)

function Badge({
  className,
  variant = "closed",
  asChild = false,
  ...props
}: React.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & { asChild?: boolean }) {
  const Comp = asChild ? Slot.Root : "span"

  return (
    <Comp
      data-slot="badge"
      data-variant={variant}
      className={cn(badgeVariants({ variant }), className)}
      {...props}
    />
  )
}

export { Badge, badgeVariants }
